const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    // Bindings for the system SQLite library.
    const sqlite_c = b.addTranslateC(.{
        .root_source_file = b.path("src/sqlite3.h"),
        .target = target,
        .optimize = optimize,
    });
    const c_mod = sqlite_c.createModule();
    c_mod.linkSystemLibrary("sqlite3", .{});

    const exe_mod = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
        .link_libc = true,
        .imports = &.{.{ .name = "c", .module = c_mod }},
    });

    const exe = b.addExecutable(.{ .name = "notes", .root_module = exe_mod });
    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());
    if (b.args) |args| run_cmd.addArgs(args);
    b.step("run", "Run the notes server").dependOn(&run_cmd.step);

    const tests = b.addTest(.{ .root_module = exe_mod });
    b.step("test", "Run unit tests").dependOn(&b.addRunArtifact(tests).step);
}

//! Persistent note storage in a SQLite database.
//!
//! A single connection is shared by all requests and serialized with a mutex;
//! SQLite is in-process and fast enough that this is not a bottleneck here.

const std = @import("std");
const Allocator = std.mem.Allocator;
const Io = std.Io;
const c = @import("c");

const sqlite = @import("sqlite.zig");
const note = @import("note.zig");
const Note = note.Note;

const Store = @This();

db: sqlite.Db,
mutex: Io.Mutex = .init,
io: Io,

pub const Error = sqlite.Error || Allocator.Error;

const schema =
    \\PRAGMA journal_mode = WAL;
    \\PRAGMA synchronous = NORMAL;
    \\PRAGMA foreign_keys = ON;
    \\CREATE TABLE IF NOT EXISTS notes (
    \\    id    INTEGER PRIMARY KEY AUTOINCREMENT,
    \\    title TEXT NOT NULL,
    \\    body  TEXT NOT NULL
    \\);
    \\CREATE TABLE IF NOT EXISTS note_tags (
    \\    note_id INTEGER NOT NULL REFERENCES notes (id) ON DELETE CASCADE,
    \\    tag     TEXT NOT NULL,
    \\    PRIMARY KEY (note_id, tag)
    \\) WITHOUT ROWID;
    \\CREATE INDEX IF NOT EXISTS note_tags_by_tag ON note_tags (tag, note_id);
;

pub fn open(io: Io, path: [:0]const u8) sqlite.Error!Store {
    const db: sqlite.Db = try .open(path);
    errdefer db.close();
    db.setBusyTimeout(5000);
    try db.exec(schema);
    try db.createScalarFunction("contains_ci", 2, containsIgnoreCase);
    return .{ .db = db, .io = io };
}

pub fn close(store: *Store) void {
    store.db.close();
    store.* = undefined;
}

pub const Filter = struct {
    tag: ?[]const u8 = null,
    query: ?[]const u8 = null,
    after: i64 = 0,
    limit: u32 = 100,
};

pub const TagCount = struct {
    tag: []const u8,
    count: i64,
};

pub const Stats = struct {
    notes: i64,
    /// Sorted by tag ascending.
    tags: []const TagCount,
};

pub fn create(store: *Store, arena: Allocator, input: note.Input) Error!Note {
    store.mutex.lockUncancelable(store.io);
    defer store.mutex.unlock(store.io);

    try store.db.exec("BEGIN IMMEDIATE");
    errdefer store.rollback();

    const insert = try store.db.prepare("INSERT INTO notes (title, body) VALUES (?, ?)");
    defer insert.deinit();
    try insert.bindAll(.{ input.title, input.body });
    try insert.run();
    const id = store.db.lastInsertRowId();

    try store.insertTags(id, input.tags);
    try store.db.exec("COMMIT");
    return try copyNote(arena, id, input);
}

/// Returns null if no note has this id.
pub fn get(store: *Store, arena: Allocator, id: i64) Error!?Note {
    store.mutex.lockUncancelable(store.io);
    defer store.mutex.unlock(store.io);

    const select = try store.db.prepare("SELECT id, title, body FROM notes WHERE id = ?");
    defer select.deinit();
    try select.bind(1, id);
    if (!try select.step()) return null;

    const tags_stmt = try store.prepareTagsQuery();
    defer tags_stmt.deinit();
    return try readNote(arena, select, tags_stmt);
}

/// Replaces a note's title, body and tags. Returns null if no note has this id.
pub fn update(store: *Store, arena: Allocator, id: i64, input: note.Input) Error!?Note {
    store.mutex.lockUncancelable(store.io);
    defer store.mutex.unlock(store.io);

    try store.db.exec("BEGIN IMMEDIATE");
    errdefer store.rollback();

    const stmt = try store.db.prepare("UPDATE notes SET title = ?, body = ? WHERE id = ?");
    defer stmt.deinit();
    try stmt.bindAll(.{ input.title, input.body, id });
    try stmt.run();
    if (store.db.changes() == 0) {
        store.rollback();
        return null;
    }

    try store.deleteTags(id);
    try store.insertTags(id, input.tags);
    try store.db.exec("COMMIT");
    return try copyNote(arena, id, input);
}

/// Returns false if no note has this id.
pub fn delete(store: *Store, id: i64) Error!bool {
    store.mutex.lockUncancelable(store.io);
    defer store.mutex.unlock(store.io);

    try store.db.exec("BEGIN IMMEDIATE");
    errdefer store.rollback();

    try store.deleteTags(id);
    const stmt = try store.db.prepare("DELETE FROM notes WHERE id = ?");
    defer stmt.deinit();
    try stmt.bind(1, id);
    try stmt.run();
    const deleted = store.db.changes() > 0;
    try store.db.exec("COMMIT");
    return deleted;
}

/// Returns the notes matching `filter`, ordered by id ascending.
pub fn list(store: *Store, arena: Allocator, filter: Filter) Error![]Note {
    store.mutex.lockUncancelable(store.io);
    defer store.mutex.unlock(store.io);

    const select = try store.db.prepare(
        \\SELECT id, title, body FROM notes AS n
        \\WHERE id > ?1
        \\  AND (?2 IS NULL OR EXISTS (SELECT 1 FROM note_tags AS t WHERE t.note_id = n.id AND t.tag = ?2))
        \\  AND (?3 IS NULL OR contains_ci(title, ?3) OR contains_ci(body, ?3))
        \\ORDER BY id
        \\LIMIT ?4
    );
    defer select.deinit();
    try select.bindAll(.{ filter.after, filter.tag, filter.query, filter.limit });

    const tags_stmt = try store.prepareTagsQuery();
    defer tags_stmt.deinit();

    var notes: std.ArrayList(Note) = .empty;
    while (try select.step()) try notes.append(arena, try readNote(arena, select, tags_stmt));
    return notes.items;
}

pub fn stats(store: *Store, arena: Allocator) Error!Stats {
    store.mutex.lockUncancelable(store.io);
    defer store.mutex.unlock(store.io);

    const count = try store.db.prepare("SELECT count(*) FROM notes");
    defer count.deinit();
    _ = try count.step();
    const notes = count.columnInt(0);

    const tags = try store.tagCounts(arena, "SELECT tag, count(*) FROM note_tags GROUP BY tag ORDER BY tag");
    return .{ .notes = notes, .tags = tags };
}

/// Returns every tag in use, ordered by count descending, then tag ascending.
pub fn tagsByCount(store: *Store, arena: Allocator) Error![]TagCount {
    store.mutex.lockUncancelable(store.io);
    defer store.mutex.unlock(store.io);

    return store.tagCounts(arena,
        \\SELECT tag, count(*) AS n FROM note_tags GROUP BY tag ORDER BY n DESC, tag ASC
    );
}

fn tagCounts(store: *Store, arena: Allocator, sql: []const u8) Error![]TagCount {
    const stmt = try store.db.prepare(sql);
    defer stmt.deinit();
    var result: std.ArrayList(TagCount) = .empty;
    while (try stmt.step()) {
        try result.append(arena, .{
            .tag = try arena.dupe(u8, stmt.columnText(0)),
            .count = stmt.columnInt(1),
        });
    }
    return result.items;
}

fn insertTags(store: *Store, id: i64, tags: []const []const u8) Error!void {
    if (tags.len == 0) return;
    const stmt = try store.db.prepare("INSERT OR IGNORE INTO note_tags (note_id, tag) VALUES (?, ?)");
    defer stmt.deinit();
    for (tags) |tag| {
        stmt.reset();
        try stmt.bindAll(.{ id, tag });
        try stmt.run();
    }
}

fn deleteTags(store: *Store, id: i64) Error!void {
    const stmt = try store.db.prepare("DELETE FROM note_tags WHERE note_id = ?");
    defer stmt.deinit();
    try stmt.bind(1, id);
    try stmt.run();
}

fn prepareTagsQuery(store: *Store) Error!sqlite.Statement {
    return store.db.prepare("SELECT tag FROM note_tags WHERE note_id = ? ORDER BY tag");
}

fn rollback(store: *Store) void {
    store.db.exec("ROLLBACK") catch {};
}

/// Reads a note from the current row of `row`, whose columns are id, title, body.
fn readNote(arena: Allocator, row: sqlite.Statement, tags_stmt: sqlite.Statement) Error!Note {
    const id = row.columnInt(0);
    const title = try arena.dupe(u8, row.columnText(1));
    const body = try arena.dupe(u8, row.columnText(2));

    tags_stmt.reset();
    try tags_stmt.bind(1, id);
    var tags: std.ArrayList([]const u8) = .empty;
    while (try tags_stmt.step()) try tags.append(arena, try arena.dupe(u8, tags_stmt.columnText(0)));

    return .{ .id = id, .title = title, .body = body, .tags = tags.items };
}

fn copyNote(arena: Allocator, id: i64, input: note.Input) Allocator.Error!Note {
    const tags = try arena.alloc([]const u8, input.tags.len);
    for (tags, input.tags) |*dst, src| dst.* = try arena.dupe(u8, src);
    return .{
        .id = id,
        .title = try arena.dupe(u8, input.title),
        .body = try arena.dupe(u8, input.body),
        .tags = tags,
    };
}

/// SQL function `contains_ci(haystack, needle)`: true if `needle` occurs in
/// `haystack`, ignoring ASCII case.
fn containsIgnoreCase(ctx: ?*c.sqlite3_context, argc: c_int, argv: [*c]?*c.sqlite3_value) callconv(.c) void {
    std.debug.assert(argc == 2);
    const haystack = sqlite.valueText(argv[0]) orelse return sqlite.resultNull(ctx);
    const needle = sqlite.valueText(argv[1]) orelse return sqlite.resultNull(ctx);
    sqlite.resultBool(ctx, std.ascii.indexOfIgnoreCase(haystack, needle) != null);
}

const testing = std.testing;

fn testInput(title: []const u8, body: []const u8, tags: []const []const u8) note.Input {
    return .{ .title = title, .body = body, .tags = tags };
}

test "create, get, update, delete" {
    var store: Store = try .open(testing.io, ":memory:");
    defer store.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    const first = try store.create(a, testInput("one", "", &.{ "a", "b" }));
    try testing.expectEqual(1, first.id);
    const second = try store.create(a, testInput("two", "body", &.{}));
    try testing.expectEqual(2, second.id);

    const got = (try store.get(a, 1)).?;
    try testing.expectEqualStrings("one", got.title);
    try testing.expectEqual(2, got.tags.len);
    try testing.expectEqual(null, try store.get(a, 3));

    const updated = (try store.update(a, 1, testInput("uno", "x", &.{"c"}))).?;
    try testing.expectEqualStrings("uno", updated.title);
    try testing.expectEqual(null, try store.update(a, 9, testInput("x", "", &.{})));
    const reread = (try store.get(a, 1)).?;
    try testing.expectEqual(1, reread.tags.len);
    try testing.expectEqualStrings("c", reread.tags[0]);

    try testing.expect(try store.delete(2));
    try testing.expect(!try store.delete(2));
    const third = try store.create(a, testInput("three", "", &.{}));
    try testing.expectEqual(3, third.id);
}

test "list filters and tag counts" {
    var store: Store = try .open(testing.io, ":memory:");
    defer store.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    _ = try store.create(a, testInput("Hello world", "", &.{"greet"}));
    _ = try store.create(a, testInput("other", "say HELLO 100%", &.{ "greet", "misc" }));
    _ = try store.create(a, testInput("nothing", "", &.{}));

    try testing.expectEqual(3, (try store.list(a, .{})).len);
    try testing.expectEqual(2, (try store.list(a, .{ .query = "hello" })).len);
    try testing.expectEqual(1, (try store.list(a, .{ .query = "0%" })).len);
    try testing.expectEqual(0, (try store.list(a, .{ .query = "_" })).len);
    const misc = try store.list(a, .{ .tag = "misc", .query = "hello" });
    try testing.expectEqual(1, misc.len);
    try testing.expectEqual(2, misc[0].id);
    try testing.expectEqual(2, misc[0].tags.len);
    const paged = try store.list(a, .{ .after = 1, .limit = 1 });
    try testing.expectEqual(1, paged.len);
    try testing.expectEqual(2, paged[0].id);

    const s = try store.stats(a);
    try testing.expectEqual(3, s.notes);
    try testing.expectEqual(2, s.tags.len);
    try testing.expectEqualStrings("greet", s.tags[0].tag);
    try testing.expectEqual(2, s.tags[0].count);

    _ = try store.delete(2);
    const by_count = try store.tagsByCount(a);
    try testing.expectEqual(1, by_count.len);
    try testing.expectEqualStrings("greet", by_count[0].tag);
    try testing.expectEqual(1, by_count[0].count);
}

//! Request routing and handlers, independent of the HTTP transport.

const std = @import("std");
const Allocator = std.mem.Allocator;
const Method = std.http.Method;
const Status = std.http.Status;

const note = @import("note.zig");
const Store = @import("Store.zig");

pub const Response = struct {
    status: Status,
    body: []const u8,
    content_type: []const u8 = "application/json",
    /// Value of the `Allow` header for 405 responses.
    allow: ?[]const u8 = null,
};

pub const Request = struct {
    method: Method,
    /// Path plus optional query string, as sent by the client.
    target: []const u8,
    body: []const u8 = "",
};

/// Handles one request. All allocations go to `arena`, which must outlive the
/// returned response.
pub fn handle(store: *Store, arena: Allocator, req: Request) Allocator.Error!Response {
    return route(store, arena, req) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        error.SqliteError => return errorResponse(arena, .internal_server_error, "database error"),
        error.WriteFailed => return error.OutOfMemory,
    };
}

const HandlerError = Store.Error || std.Io.Writer.Error;

fn route(store: *Store, arena: Allocator, req: Request) HandlerError!Response {
    const path, const query = splitTarget(req.target);

    if (std.mem.eql(u8, path, "/health")) {
        if (!isGet(req.method)) return methodNotAllowed(arena, "GET");
        return .{ .status = .ok, .body = "ok", .content_type = "text/plain" };
    }
    if (std.mem.eql(u8, path, "/notes")) return switch (req.method) {
        .GET, .HEAD => listNotes(store, arena, query),
        .POST => createNote(store, arena, req.body),
        else => methodNotAllowed(arena, "GET, POST"),
    };
    if (std.mem.startsWith(u8, path, "/notes/")) {
        const id = parseId(path["/notes/".len..]) orelse return notFound(arena);
        return switch (req.method) {
            .GET, .HEAD => getNote(store, arena, id),
            .PUT => updateNote(store, arena, id, req.body),
            .DELETE => deleteNote(store, arena, id),
            else => methodNotAllowed(arena, "GET, PUT, DELETE"),
        };
    }
    if (std.mem.eql(u8, path, "/stats")) {
        if (!isGet(req.method)) return methodNotAllowed(arena, "GET");
        return stats(store, arena);
    }
    if (std.mem.eql(u8, path, "/tags")) {
        if (!isGet(req.method)) return methodNotAllowed(arena, "GET");
        return tags(store, arena);
    }
    return notFound(arena);
}

fn createNote(store: *Store, arena: Allocator, body: []const u8) HandlerError!Response {
    const input = note.parseInput(arena, body) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        else => |e| return errorResponse(arena, .bad_request, note.errorMessage(e)),
    };
    const created = try store.create(arena, input);
    return jsonResponse(arena, .created, created);
}

fn getNote(store: *Store, arena: Allocator, id: i64) HandlerError!Response {
    const found = try store.get(arena, id) orelse return notFound(arena);
    return jsonResponse(arena, .ok, found);
}

fn updateNote(store: *Store, arena: Allocator, id: i64, body: []const u8) HandlerError!Response {
    const input = note.parseInput(arena, body) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        else => |e| return errorResponse(arena, .bad_request, note.errorMessage(e)),
    };
    const updated = try store.update(arena, id, input) orelse return notFound(arena);
    return jsonResponse(arena, .ok, updated);
}

fn deleteNote(store: *Store, arena: Allocator, id: i64) HandlerError!Response {
    if (!try store.delete(id)) return notFound(arena);
    return .{ .status = .no_content, .body = "" };
}

fn listNotes(store: *Store, arena: Allocator, query: []const u8) HandlerError!Response {
    const filter = parseFilter(arena, query) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        error.InvalidLimit => return errorResponse(arena, .bad_request, "limit must be an integer from 1 to 100"),
        error.InvalidAfter => return errorResponse(arena, .bad_request, "after must be a non-negative integer"),
    };
    const notes = try store.list(arena, filter);
    return jsonResponse(arena, .ok, .{ .notes = notes });
}

fn stats(store: *Store, arena: Allocator) HandlerError!Response {
    const s = try store.stats(arena);
    var out: std.Io.Writer.Allocating = .init(arena);
    var json: std.json.Stringify = .{ .writer = &out.writer };
    try json.beginObject();
    try json.objectField("notes");
    try json.write(s.notes);
    try json.objectField("tags");
    try json.beginObject();
    for (s.tags) |t| {
        try json.objectField(t.tag);
        try json.write(t.count);
    }
    try json.endObject();
    try json.endObject();
    return .{ .status = .ok, .body = out.written() };
}

fn tags(store: *Store, arena: Allocator) HandlerError!Response {
    const counts = try store.tagsByCount(arena);
    return jsonResponse(arena, .ok, .{ .tags = counts });
}

fn isGet(method: Method) bool {
    return method == .GET or method == .HEAD;
}

fn jsonResponse(arena: Allocator, status: Status, value: anytype) Allocator.Error!Response {
    return .{ .status = status, .body = try std.json.Stringify.valueAlloc(arena, value, .{}) };
}

fn errorResponse(arena: Allocator, status: Status, message: []const u8) Allocator.Error!Response {
    return jsonResponse(arena, status, .{ .@"error" = message });
}

fn notFound(arena: Allocator) Allocator.Error!Response {
    return errorResponse(arena, .not_found, "not found");
}

fn methodNotAllowed(arena: Allocator, allow: []const u8) Allocator.Error!Response {
    var response = try errorResponse(arena, .method_not_allowed, "method not allowed");
    response.allow = allow;
    return response;
}

/// Splits a request target into its path and query string.
fn splitTarget(target: []const u8) struct { []const u8, []const u8 } {
    const without_fragment = target[0 .. std.mem.indexOfScalar(u8, target, '#') orelse target.len];
    const q = std.mem.indexOfScalar(u8, without_fragment, '?') orelse
        return .{ without_fragment, "" };
    return .{ without_fragment[0..q], without_fragment[q + 1 ..] };
}

/// Parses a note id: a positive decimal integer without sign.
fn parseId(text: []const u8) ?i64 {
    const id = parseUnsigned(text) orelse return null;
    return if (id > 0) id else null;
}

fn parseUnsigned(text: []const u8) ?i64 {
    if (text.len == 0) return null;
    for (text) |ch| if (!std.ascii.isDigit(ch)) return null;
    return std.fmt.parseInt(i64, text, 10) catch null;
}

const FilterError = error{ InvalidLimit, InvalidAfter } || Allocator.Error;

fn parseFilter(arena: Allocator, query: []const u8) FilterError!Store.Filter {
    var filter: Store.Filter = .{};
    var seen: struct { tag: bool = false, q: bool = false, after: bool = false, limit: bool = false } = .{};

    var params = std.mem.splitScalar(u8, query, '&');
    while (params.next()) |param| {
        if (param.len == 0) continue;
        const eq = std.mem.indexOfScalar(u8, param, '=');
        const key = try percentDecode(arena, param[0 .. eq orelse param.len]);
        const value = try percentDecode(arena, if (eq) |i| param[i + 1 ..] else "");

        // The first occurrence of a parameter wins.
        if (std.mem.eql(u8, key, "tag")) {
            if (seen.tag) continue;
            seen.tag = true;
            filter.tag = value;
        } else if (std.mem.eql(u8, key, "q")) {
            if (seen.q) continue;
            seen.q = true;
            filter.query = value;
        } else if (std.mem.eql(u8, key, "after")) {
            if (seen.after) continue;
            seen.after = true;
            filter.after = parseUnsigned(value) orelse return error.InvalidAfter;
        } else if (std.mem.eql(u8, key, "limit")) {
            if (seen.limit) continue;
            seen.limit = true;
            const limit = parseUnsigned(value) orelse return error.InvalidLimit;
            if (limit < 1 or limit > 100) return error.InvalidLimit;
            filter.limit = @intCast(limit);
        }
    }
    return filter;
}

/// Decodes `application/x-www-form-urlencoded` text: `+` is a space and `%XX`
/// is a byte. Malformed escapes are kept literally.
fn percentDecode(arena: Allocator, text: []const u8) Allocator.Error![]const u8 {
    if (std.mem.indexOfAny(u8, text, "%+") == null) return text;
    const out = try arena.alloc(u8, text.len);
    var len: usize = 0;
    var i: usize = 0;
    while (i < text.len) : (len += 1) {
        if (text[i] == '+') {
            out[len] = ' ';
            i += 1;
        } else if (text[i] == '%' and i + 2 < text.len and hexByte(text[i + 1 ..][0..2]) != null) {
            out[len] = hexByte(text[i + 1 ..][0..2]).?;
            i += 3;
        } else {
            out[len] = text[i];
            i += 1;
        }
    }
    return out[0..len];
}

fn hexByte(digits: *const [2]u8) ?u8 {
    const hi = std.fmt.charToDigit(digits[0], 16) catch return null;
    const lo = std.fmt.charToDigit(digits[1], 16) catch return null;
    return hi << 4 | lo;
}

const testing = std.testing;

test splitTarget {
    const path, const query = splitTarget("/notes?tag=a&q=b");
    try testing.expectEqualStrings("/notes", path);
    try testing.expectEqualStrings("tag=a&q=b", query);
    const bare, const empty = splitTarget("/notes");
    try testing.expectEqualStrings("/notes", bare);
    try testing.expectEqualStrings("", empty);
}

test parseId {
    try testing.expectEqual(12, parseId("12"));
    try testing.expectEqual(null, parseId("0"));
    try testing.expectEqual(null, parseId("-1"));
    try testing.expectEqual(null, parseId("+1"));
    try testing.expectEqual(null, parseId("abc"));
    try testing.expectEqual(null, parseId(""));
    try testing.expectEqual(null, parseId("1/"));
    try testing.expectEqual(null, parseId("99999999999999999999"));
}

test percentDecode {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    try testing.expectEqualStrings("hello world", try percentDecode(a, "hello+world"));
    try testing.expectEqualStrings("a b&c", try percentDecode(a, "a%20b%26c"));
